<?php
namespace Tests\Unit;
use PHPUnit\Framework\TestCase;
class Erp409CostingTest extends TestCase
{
 protected $order_id; protected $item_id; protected $price_id; protected $movement_id; protected $operation_id; protected $center_id;
 protected function setUp():void{try{\DB::select('id')->from('erp_409_calculations')->limit(1)->execute();}catch(\Throwable $e){$this->markTestSkipped('Выполните миграции erp409');}}
 protected function tearDown():void{try{if($this->order_id){$ids=\DB::select('id')->from('erp_409_calculations')->where('order_id','=',$this->order_id)->execute()->as_array(NULL,'id');if($ids)\DB::delete('erp_409_lines')->where('calculation_id','IN',$ids)->execute();\DB::delete('erp_409_calculations')->where('order_id','=',$this->order_id)->execute();}if($this->operation_id)\DB::delete('erp_408_operations')->where('id','=',$this->operation_id)->execute();if($this->center_id)\DB::delete('erp_408_work_centers')->where('id','=',$this->center_id)->execute();if($this->movement_id)\DB::delete('erp_401_movements')->where('id','=',$this->movement_id)->execute();if($this->price_id)\DB::delete('erp_403_prices')->where('id','=',$this->price_id)->execute();if($this->order_id){\DB::delete('erp_402_order_items')->where('order_id','=',$this->order_id)->execute();\DB::delete('erp_402_orders')->where('id','=',$this->order_id)->execute();}if($this->item_id)\DB::delete('erp_227_objects')->where('id','=',$this->item_id)->execute();}catch(\Throwable $e){}}
 protected function fixture(){if($this->order_id)return;$type=(int)\DB::select('id')->from('erp_227_object_types')->where('code','=','component')->execute()->get('id');$this->item_id=(int)\DB::insert('erp_227_objects',array('type_id','code','name','status','is_deleted'))->values(array($type,'TEST-409-MAT','Материал costing','active',FALSE))->execute()[0];$supplier=(int)\DB::select('id')->from('erp_301_counterparties')->order_by('id')->execute()->get('id');$this->price_id=(int)\DB::insert('erp_403_prices',array('supplier_id','item_id','name','price','qty','currency','uom_code','source','dated_at'))->values(array($supplier,$this->item_id,'Материал costing',100,10,'RUB','pcs','manual',date('Y-m-d H:i:s',time()-60)))->execute()[0];$warehouse=(int)\DB::select('id')->from('erp_401_warehouses')->order_by('id')->execute()->get('id');$this->order_id=(int)\DB::insert('erp_402_orders',array('number','title','uom_code','qty','qty_done','status','warehouse_id','output_warehouse_id'))->values(array('ПО-ТЕСТ-409','Тест costing','pcs',10,9,'done',$warehouse,$warehouse))->execute()[0];\DB::insert('erp_402_order_items',array('order_id','line_no','item_id','name','uom_code','qty_per_unit','qty_total','qty_issued','warehouse_id','status'))->values(array($this->order_id,10,$this->item_id,'Материал costing','pcs',1,10,8,$warehouse,'issued'))->execute();$this->movement_id=(int)\DB::insert('erp_401_movements',array('type','item_id','uom_code','warehouse_id','qty','balance_before','balance_after','status','doc_type','doc_id'))->values(array('issue',$this->item_id,'pcs',$warehouse,8,8,0,'posted','erp402_order',$this->order_id))->execute()[0];$this->center_id=(int)\DB::insert('erp_408_work_centers',array('uuid','code','name','kind','cost_per_hour','is_active'))->values(array(\Erp::uuid(),'TEST-409-C','Центр costing','center',30,TRUE))->execute()[0];$this->operation_id=(int)\DB::insert('erp_408_operations',array('uuid','order_id','order_number','order_title','qty_planned','op_no','name','work_center_id','planned_hours','norm_cost','status','qty_ok','qty_scrap','worked_sec'))->values(array(\Erp::uuid(),$this->order_id,'ПО-ТЕСТ-409','Тест costing',10,10,'Операция costing',$this->center_id,2,50,'done',9,1,3600))->execute()[0];}
 public function test_calculation_is_versioned_and_explains_rate_sources(){ $this->fixture();$s=\Service_Erp409_Costing::instance();$a=$s->calculate($this->order_id,1);$this->assertSame(1,(int)$a['version']);$this->assertEquals(210,(float)$a['planned_total']);$this->assertEquals(135,(float)$a['actual_total']);$this->assertEquals(13.5,(float)$a['scrap_loss']);$this->assertEquals(15,(float)$a['actual_unit_cost']);$this->assertCount(7,$a['lines']);foreach($a['lines'] as $line){$this->assertNotEmpty($line['rate_source']);$this->assertNotEmpty($line['source_type']);} $b=$s->calculate($this->order_id,1);$this->assertSame(2,(int)$b['version']);}
 public function test_approval_is_human_state_and_mcp_stays_read_only(){ $this->fixture();$calc=\Service_Erp409_Costing::instance()->calculate($this->order_id,1);$approved=\Service_Erp409_Costing::instance()->approve($calc['id'],1);$this->assertSame('approved',$approved['status']);$tools=\Service_Erp804_Registry::instance()->tools();foreach(array('costing.orders','costing.explain') as $name){$this->assertArrayHasKey($name,$tools);$this->assertFalse($tools[$name]['mutating']);}}
 public function test_ui_routes_navigation_and_shared_components_are_discoverable(){ $nav=\Ui_Navigation::palette(array('login','manager'));$this->assertContains('/costing',array_column($nav,'href'));$main=file_get_contents(APPPATH.'modules/erp409_costing/classes/Controller/Erp409/Main.php');$this->assertStringContainsString('set_menu(',$main);foreach(array('index.php','view.php') as $view){$source=file_get_contents(APPPATH.'modules/erp409_costing/views/erp409/'.$view);$this->assertStringContainsString("Component::render('table'",$source);$this->assertStringNotContainsString('<table',$source);}}
}
